    "ctpFittings.heroDescription": "SUPERLIT CTP Fittings provide superior solutions that ensure reliability and performance in your pipe systems. Made from Glass Fiber Reinforced Polyester (GRP) material, these fittings stand out with their high strength, corrosion resistance and long service life. Designed and manufactured in accordance with international standards, they can be used in drinking water, wastewater, industrial facilities and power plants. With flexible installation options and superior sealing structure, they offer maximum efficiency and safety in your projects.",
    "ctpFittings.heroFeature1": "High Strength",
    "ctpFittings.heroFeature2": "Corrosion Resistant",
