    "ctpFittings.equalTees": "Equal Tees",
    "ctpFittings.equalTeesDesc": "Equal tees are used to create branch connections of the same diameter in pipe systems. SUPERLIT equal tees are manufactured from CTP material and provide high strength and sealing performance.",
