    "ctpFittings.unequalNote3": "Custom dimensions available upon request",
    "ctpFittings.elbowsTitle": "Elbows",
    "ctpFittings.elbowsDesc": "CTP elbows are used to change direction in pipe systems. They are available in various angle ranges and pressure classes to meet different project requirements.",
