    "ctpFittings.flangesTitle": "Flanges",
    "ctpFittings.flangesDesc": "CTP flanges are used for bolted connections in pipe systems. They provide a reliable and dismountable connection point for valves, pumps and other equipment.",
    "ctpFittings.flangeType1": "Stub End Flanges - For connection to steel or ductile iron flanges",
    "ctpFittings.flangeType2": "Full-Face Flanges - Integrated sealing surface for maximum tightness",
    "ctpFittings.flangeType3": "Blind Flanges - For closing pipe ends",
