    // CTP Menhol Page
    "ctpMenhol.pageTitle": "CTP Menhol",
    "ctpMenhol.heroTitle": "CTP Menhol",
    "ctpMenhol.heroDesc": "SUPERLIT's CTP Manhole solutions stand out in the industry for their durability and reliability. Our manholes, produced from Glass Fiber Reinforced Polyester (GRP) material, provide excellent performance in infrastructure projects.",
    "ctpMenhol.tab1Label": "PRODUCT DESCRIPTION",
    "ctpMenhol.tab2Label": "IMAGE GALLERY",
    "ctpMenhol.tab1Title1": "CTP",
    "ctpMenhol.tab1Title2": "MENHOL",
    "ctpMenhol.tab1ShortDesc": "SUPERLIT CTP Manholes, used in a wide range of applications from water and wastewater management systems to industrial facilities, are designed and manufactured in compliance with international standards.",
    "ctpMenhol.tab1WhatIs": "What is CTP Manhole?",
    "ctpMenhol.tab1WhatIsDesc": "CTP Manholes are produced from composite materials consisting of glass fiber reinforced thermoset resin and silica sand. This material combination provides manholes with high strength, corrosion resistance, and long service life. CTP Manholes can be used in both underground and above-ground applications and meet various industrial needs.",
    "ctpMenhol.tab1UsageTitle": "Application Areas of CTP Manholes",
    "ctpMenhol.tab1UsageDesc": "SUPERLIT CTP Manholes are used in water and wastewater management systems, industrial facilities, piping lines of chemical plants, power plant circulation lines, and hydroelectric power plant transmission lines. They are also preferred in stormwater and drainage systems, sewage lines, and submarine piping applications.",
    "ctpMenhol.tab1AdvTitle": "Advantages of CTP Manholes",
    "ctpMenhol.tab1AdvDesc": "CTP Manholes stand out with their long-lasting and durable structure. These manholes, offering a minimum 50-year service life, provide superior resistance to corrosion and perform flawlessly across a wide pH range. Their lightweight structure offers great convenience in transportation and assembly. CTP Manholes, much lighter than steel, ductile, and concrete manholes, do not require special equipment during installation and allow for quick setup.",
    "ctpMenhol.tab1AdvDesc2": "SUPERLIT CTP Manholes, with their smooth inner surface, offer low hydraulic losses and minimum friction, ensuring efficient water and wastewater transmission. Full-face (Full-FaceÂ®) integrated elastomeric gasket couplings provide leak-tight and reliable connections.",
    "ctpMenhol.tab1QualityTitle": "Quality and Safety",
    "ctpMenhol.tab1QualityDesc": "SUPERLIT manufactures CTP Manholes in compliance with the highest quality standards. Our manholes, produced according to EN, ISO, ASTM, and AWWA standards, meet needs across a wide diameter range and various pressure classes. Our products offer reliable, durable, and efficient solutions for your engineering projects.",
    "ctpMenhol.tab1QualityDesc2": "SUPERLIT's CTP Manhole solutions are an environmentally friendly choice for sustainable projects, manufactured from recyclable materials at the end of their service life. With its long-lasting and environmentally friendly structure, SUPERLIT CTP Manhole is a product you can confidently choose for your infrastructure projects.",

    // CTP Tank Page
    "ctpTank.pageTitle": "CTP Tank",
    "ctpTank.heroTitle": "CTP Tank",
    "ctpTank.heroDesc": "SUPERLIT, as a leader in water transmission and storage solutions, offers CTP (Glass Fiber Reinforced Polyester) tank systems with superior durability and reliability. Whether for drinking water or chemical storage, these tanks provide long-lasting and environmentally friendly solutions.",
    "ctpTank.tab1Label": "PRODUCT DESCRIPTION",
    "ctpTank.tab2Label": "IMAGE GALLERY",
    "ctpTank.tab1Title1": "CTP",
    "ctpTank.tab1Title2": "TANK",
    "ctpTank.tab1ShortDesc": "In addition to the pipes used in water transmission, SUPERLIT also offers the best solutions for water storage needs with CTP (Glass Fiber Reinforced Polyester) tank systems.",
    "ctpTank.tab1SystemsTitle": "CTP Tank Systems: Reliable and Durable Storage Solutions",
    "ctpTank.tab1SystemsDesc": "Thanks to their mechanical, thermal and chemical resistance, CTP tank systems hold an important place in the preservation of water under healthy environmental conditions. These tanks are preferred because their lightweight structure provides a great advantage in transportation, they do not require any additional installation costs and they minimize installation time.",
    "ctpTank.tab1AdvTitle": "Product Advantages:",
    "ctpTank.tab1Adv1": "Continuous Drinkable Water Quality: Provides continuous drinkable water quality as no paint or chemicals are added.",
    "ctpTank.tab1Adv2": "Smooth Inner Surface: Does not get dirty and does not hold algae.",
    "ctpTank.tab1Adv3": "Corrosion Resistance: Provides superior corrosion resistance compared to steel and concrete tanks.",
    "ctpTank.tab1Adv4": "Lightweight: Compared to other materials, it is lightweight, which provides ease of transport and installation.",
    "ctpTank.tab1Adv5": "Short Construction Time: Construction time is short thanks to fast and easy installation.",
    "ctpTank.tab1Adv6": "Expandability: Can be easily added to the existing system when needed.",
    "ctpTank.tab1Adv7": "UV Resistance: Resistant to UV rays.",
    "ctpTank.tab1AppTitle": "CTP Tank Applications:",
    "ctpTank.tab1App1": "Clean Water and Drinking Water: Healthy and safe drinking water storage solutions.",
    "ctpTank.tab1App2": "Rainwater Collection: Collects flood waters and reclaims them for irrigation and other usage areas.",
    "ctpTank.tab1App3": "Chemical Storage: The ability to store a wide variety of chemicals safely and economically.",
    "ctpTank.tab1App4": "Petroleum Storage: Ideal for safe storage of petroleum-based chemicals.",
    "ctpTank.tab1DesignTitle": "Design and Accessories:",
    "ctpTank.tab1Design1": "Manholes and Nozzles: Can be designed according to project requirements, available in different diameters and specifications.",
    "ctpTank.tab1Design2": "Ladders and Lifting Rings: Necessary accessories for ease of use and maintenance of the tank.",
    "ctpTank.tab1Design3": "CTP Supports: Specially designed support elements for above-ground applications.",
    "ctpTank.tab1InstallTitle": "Installation and Transport:",
    "ctpTank.tab1Install1": "Quick Installation: CTP tanks offer fast and easy installation. The use of polyester slings instead of steel cable or chain during installation is recommended.",
    "ctpTank.tab1Install2": "Storage: Tanks should be stored in their original packaging before installation. The storage area should be flat and clean.",
    "ctpTank.tab1Install3": "Underground Tanks: Safety and stability should be prioritized during excavation and trench preparation.",
    "ctpTank.tab1Conclusion": "The CTP tank systems offered by SUPERLIT provide reliable, durable and economical solutions for your projects. Designed and produced to suit your different needs in both above-ground and underground applications, these tanks are a long-lasting and environmentally friendly option in the field of water and chemical storage.",

