    // Marine Lug Page
    "marineLug.pageTitle": "Marine LugÂ® ÑÐ¸ÑÑ‚ÐµÐ¼Ð¸",
    "marineLug.heroTitle": "Marine LugÂ® ÑÐ¸ÑÑ‚ÐµÐ¼Ð¸",
    "marineLug.heroDesc": "Ð¡Ð¿ÐµÑ†Ð¸Ñ˜Ð°Ð»Ð½Ð¸Ð¾Ñ‚ Marine LugÂ® ÑÐ¸ÑÑ‚ÐµÐ¼, Ð¿Ð°Ñ‚ÐµÐ½Ñ‚Ð¸Ñ€Ð°Ð½ Ð¾Ð´ Ð¸Ð½Ð¶ÐµÐ½ÐµÑ€Ð¸Ñ‚Ðµ Ð½Ð° SUPERLIT Ð·Ð° Ð¿Ð¾Ð»Ð°Ð³Ð°ÑšÐµ Ð½Ð° Ñ†ÐµÐ²ÐºÐ¸ ÑÐ¾ Ð³Ð¾Ð»ÐµÐ¼ Ð´Ð¸Ñ˜Ð°Ð¼ÐµÑ‚Ð°Ñ€ Ð¿Ð¾Ð´ Ð²Ð¾Ð´Ð°, Ðµ Ð¸Ð½Ð¾Ð²Ð°Ñ‚Ð¸Ð²Ð½Ð¾ Ñ€ÐµÑˆÐµÐ½Ð¸Ðµ ÐºÐ¾Ðµ Ð³Ð¸ Ð¾Ð»ÐµÑÐ½ÑƒÐ²Ð° Ð¾Ð¿ÐµÑ€Ð°Ñ†Ð¸Ð¸Ñ‚Ðµ Ð·Ð° Ð¿Ð¾Ð»Ð°Ð³Ð°ÑšÐµ Ñ†ÐµÐ²ÐºÐ¸ Ð¿Ð¾Ð´ Ð²Ð¾Ð´Ð°. Marine LugÂ® ÑÐ¸ÑÑ‚ÐµÐ¼Ð¸Ñ‚Ðµ Ð²Ð¸ Ð¾Ð²Ð¾Ð·Ð¼Ð¾Ð¶ÑƒÐ²Ð°Ð°Ñ‚ ÐµÐ´Ð½Ð¾ÑÑ‚Ð°Ð²Ð½Ð¾ Ð¸ ÐµÑ„Ð¸ÐºÐ°ÑÐ½Ð¾ Ð¼Ð¾Ð½Ñ‚Ð¸Ñ€Ð°ÑšÐµ Ð½Ð° Ñ†ÐµÐ²ÐºÐ¸ Ð¿Ð¾Ð´ Ð²Ð¾Ð´Ð°.",
    "marineLug.badge1": "ÐŸÐ°Ñ‚ÐµÐ½Ñ‚Ð¸Ñ€Ð°Ð½ Ð´Ð¸Ð·Ð°Ñ˜Ð½",
