    "marineLug.badge3": "Ð’Ð¸ÑÐ¾ÐºÐ° Ð¸Ð·Ð´Ñ€Ð¶Ð»Ð¸Ð²Ð¾ÑÑ‚",
    "marineLug.tab1Label": "ÐžÐŸÐ˜Ð¡ ÐÐ ÐŸÐ ÐžÐ˜Ð—Ð’ÐžÐ”",
    "marineLug.tab2Label": "Ð“ÐÐ›Ð•Ð Ð˜ÐˆÐ ÐÐ Ð¡Ð›Ð˜ÐšÐ˜",
    "marineLug.tab3Label": "Ð’Ð˜Ð”Ð•Ðž Ð“ÐÐ›Ð•Ð Ð˜ÐˆÐ",
    "marineLug.tab1SystemsTitle": "Aqua-Montagesystem",
    "marineLug.tab1ShortDesc": "Zu den innovativen Ingenieurlösungen gehören die Aqua-Montagesysteme, ein patentiertes System zur Unterwasserverlegung von Rohrleitungen, das speziell für die Installation von Rohrleitungen mit großen Durchmessern entwickelt wurde.",
    "marineLug.details": "Ð”Ð•Ð¢ÐÐ›Ð˜",
    "marineLug.tab1WhatTitle": "Was ist ein Unterwasser-Rohrinstallationssystem?",
    "marineLug.tab1WhatDesc": "Ein Unterwasser-Rohrinstallationssystem erleichtert die Montage von Rohrleitungen unter Wasser und stellt gleichzeitig sicher, dass die Rohre während der Installation stabil in ihrer Position bleiben, bis der Verfüllvorgang abgeschlossen ist. Dank der Stahl-Lug-Ringe und der benutzerfreundlichen Konstruktion ermöglichen Unterwasser-Rohrinstallationssysteme eine sichere, effiziente und wirtschaftliche Verlegung von Rohrleitungen unter Wasser. Gleichzeitig wird die Sicherheit von Tauchern erhöht, während Unternehmen von reduzierten Installationskosten und kürzeren Bauzeiten profitieren.",
    "marineLug.tab1AdvTitle": "Vorteile der Aqua-Montagesysteme:",
    "marineLug.tab1Adv1": "Stahl-Lug-Ringe: Die aus hochfestem Stahl gefertigten Lug-Ringe sorgen dafür, dass die Rohre während der Unterwasserinstallation sicher in ihrer Position bleiben.",
    "marineLug.tab1Adv2": "Drehmechanismus: Durch die Drehfunktion lassen sich die Lug-Elemente leicht in ihre vorgesehenen Aufnahmen einsetzen, was die Montage deutlich erleichtert.",
    "marineLug.tab1Adv3": "Einfache Demontage: Nach Abschluss der Rohrverlegung können die Lug-Ringe problemlos entfernt werden, wodurch das System flexibel und wiederverwendbar bleibt.",
    "marineLug.tab1Adv4": "Schnelle und einfache Installation: Die neu entwickelten Aqua-Montagesysteme ermöglichen eine besonders schnelle und unkomplizierte Montage und sparen dadurch Zeit und Arbeitsaufwand.",
    "marineLug.tab1UsageTitle": "Anwendungen und Eigenschaften",
    "marineLug.tab1UsageDesc": "Aqua-Montagesysteme sind besonders wichtig für Unterwasserarbeiten durch Taucher, deren Arbeitszeit unter Wasser begrenzt ist. Das System ermöglicht eine schnelle, sichere und präzise Verlegung von Rohrleitungen, wodurch Risiken für Taucher reduziert und Projektzeiten verkürzt werden. Unternehmen profitieren gleichzeitig von höherer Effizienz, geringeren Kosten und einem optimierten Installationsprozess.",
    "marineLug.tab1FeatTitle": "ÐšÐ°Ñ€Ð°ÐºÑ‚ÐµÑ€Ð¸ÑÑ‚Ð¸ÐºÐ¸ Ð½Ð° Ð¿Ñ€Ð¾Ð¸Ð·Ð²Ð¾Ð´Ð¾Ñ‚:",
    "marineLug.tab1Feat1": "Stahl-Lug-Ringe: hohe Stabilität und lange Lebensdauer.",
    "marineLug.tab1Feat2": "Drehmechanismus: erleichtert die Installation.",
    "marineLug.tab1Feat3": "Einfache Demontage: hohe Flexibilität und Wiederverwendbarkeit.",
    "marineLug.tab1Feat4": "Schnelle Produktion und Installation: Zeit- und Kosteneinsparungen.",
    "marineLug.tab1WhyTitle": "Warum Aqua-Montagesysteme?",
    "marineLug.tab1WhyDesc": "Die Aqua-Montagesysteme bieten eine zuverlässige, wirtschaftliche und sichere Lösung für die Unterwasserverlegung von Rohrleitungen. Ihr innovatives Design verbessert die Arbeitssicherheit für Taucher, beschleunigt Installationsprozesse und erhöht die Effizienz bei maritimen Infrastrukturprojekten.",
    "marineLug.video1Title": "ÐšÐ°ÐºÐ¾ ÑÐµ Ð¿Ð¾Ð»Ð°Ð³Ð°Ð°Ñ‚ CTP Ñ†ÐµÐ²ÐºÐ¸ Ð¿Ð¾Ð´ Ð²Ð¾Ð´Ð°? Ð—Ð°Ð¿Ð¾Ð·Ð½Ð°Ñ˜Ñ‚Ðµ ÑÐµ ÑÐ¾ Ð¿Ð°Ñ‚ÐµÐ½Ñ‚Ð¸Ñ€Ð°Ð½Ð¸Ð¾Ñ‚ Marine Lug Ð¿Ñ€Ð¾Ð¸Ð·Ð²Ð¾Ð´ Ñ€Ð°Ð·Ð²Ð¸ÐµÐ½ Ð¾Ð´ Superlit.",
    "marineLug.video2Title": "Superlit CTP Ñ†ÐµÐ²ÐºÐ¸ â€“ Ð˜ÑÐºÐµÐ½Ð´ÐµÑ€ÑƒÐ½ â€“ Ð¥Ð°Ñ‚Ð°Ñ˜ 2 x 600 MW Ð¢ÐµÑ€Ð¼Ð¾ÐµÐ»ÐµÐºÑ‚Ñ€Ð°Ð½Ð° ÐŸÑ€Ð¾ÐµÐºÑ‚ â€“ ATLAS â€“ ÐŸÑ€ÐµÑ‚ÑÑ‚Ð°Ð²ÑƒÐ²Ð°ÑšÐµ Ð½Ð° Ð¿Ñ€Ð¾ÐµÐºÑ‚Ð¾Ñ‚",
