    // Privacy Policy Page - German
    "privacyPage.backToHome": "Zurück zur Startseite",
    "privacyPage.privacySecurity": "DATENSCHUTZ & SICHERHEIT",
    "privacyPage.privacyPolicy": "DATENSCHUTZRICHTLINIE",
    "privacyPage.heroDescription": "Vertrauen zu gewinnen und zu erhalten ist wesentlich für das, was wir tun. Erfahren Sie, wie wir Ihre persÃ¶nlichen Daten schützen.",
    "privacyPage.lastUpdated": "Zuletzt aktualisiert: 4. Dezember 2024",
    "privacyPage.generalInformation": "Allgemeine Informationen zum Datenschutz und Schutz personenbezogener Daten",
    "privacyPage.generalInfoText1": "Vertrauen zu gewinnen und zu erhalten ist wesentlich für das, was wir tun. Daher sind wir wirklich verpflichtet zu Transparenz in unserer Beziehung und zur Umsetzung von Datenschutzpraktiken. Alle personenbezogenen Informationen und Daten, die uns offengelegt werden und als personenbezogene Daten gelten, werden nur verarbeitet, wenn es eine rechtliche Grundlage dafür gibt - insbesondere für einen definierten Zweck und mit Ihrer Zustimmung, wo dies erforderlich ist.",
    "privacyPage.generalInfoText2": "Daher laden wir Sie ein, sich mit vollem Vertrauen bezüglich des Schutzes Ihrer personenbezogenen Daten und anderer vertraulicher Informationen an allen unseren AktivitÃ¤ten zu beteiligen. Wir sammeln keine personenbezogenen Informationen oder Daten von Kindern.",
    "privacyPage.generalInfoText3": "Dieses Dokument ist eine Datenschutzrichtlinie und kann Ihnen helfen, die notwendigen Informationen darüber zu finden, wie wir mit Ihren personenbezogenen Daten umgehen. Bitte lesen Sie das Dokument sorgfÃ¤ltig und gründlich durch, um besser zu verstehen, welche personenbezogenen Daten wir sammeln, wie wir sie sammeln, zu welchem Zweck wir sie verwenden, mit wem wir sie teilen, wie lange wir sie speichern und wem wir Ihre personenbezogenen Daten offenlegen. Unsere Datenschutzrichtlinie wird regelmÃ¤ÃŸig aktualisiert oder geÃ¤ndert, je nach unseren AktivitÃ¤ten und Bedürfnissen, und Sie werden rechtzeitig informiert.",
    "privacyPage.contactInfoController": "Kontaktinformationen für den Verantwortlichen",
    "privacyPage.controllerText1": "Konti Hidroplast Dooel Gevgelija handelt gemÃ¤ÃŸ dem Gesetz zum Schutz personenbezogener Daten (Amtsblatt der Republik Nordmazedonien Nr. 42/2020) als Verantwortlicher für die personenbezogenen Daten, die wir verarbeiten, es sei denn, es ist in diesem Dokument anders angegeben.",
    "privacyPage.controllerText2": "Sie kÃ¶nnen uns über mehrere Wege kontaktieren, einschlieÃŸlich Telefon, E-Mail, Live-Chat oder per Post. Weitere Details finden Sie auf unserer Website:",
    "privacyPage.ourPostalAddress": "Unsere Postanschrift ist:",
    "privacyPage.dataProtectionOfficer": "Kontaktdaten des Datenschutzbeauftragten",
    "privacyPage.dpoText": "Unser bevollmÃ¤chtigter Datenschutzbeauftragter kann kontaktiert werden unter",
    "privacyPage.howWeObtainInfo": "Wie erhalten wir die Informationen und personenbezogenen Daten, die wir verarbeiten?",
    "privacyPage.obtainInfoText": "Die meisten personenbezogenen Daten und Informationen, die wir verarbeiten, werden direkt von Ihnen bereitgestellt, aus einem der folgenden Gründe:",
    "privacyPage.accessProducts": "Sie wÃ¤hlen den Zugang zu unseren Produkten, Dienstleistungen und Ressourcen.",
    "privacyPage.submitInquiry": "Sie reichen eine Anfrage für Informationen ein.",
    "privacyPage.applyJob": "Sie bewerben sich für eine Stelle bei uns.",
    "privacyPage.representOrganization": "Sie vertreten Ihre Organisation bei Meetings und Besuchen in unseren RÃ¤umlichkeiten.",
    "privacyPage.videoSurveillance": "Videoüberwachung",
    "privacyPage.videoSurveillanceText1": "Konti Hidroplast Dooel Gevgelija führt als Verantwortlicher für personenbezogene Daten Videoüberwachung in seinen Büros, Lagern, Produktionsanlagen und im Hof durch. WÃ¤hrend dieses Prozesses werden physische und physiologische Merkmale in Form von Aufnahmen von Mitarbeitern und Besuchern bei Konti Hidroplast verarbeitet. Weitere Details über die Zwecke der Videoüberwachung und die Kategorien der verarbeiteten personenbezogenen Daten finden Sie auf unserer Website in der DatenschutzerklÃ¤rung für Videoüberwachung.",
    "privacyPage.videoSurveillanceText2": "Typischerweise sind die personenbezogenen Daten, die wir sammeln, auf die Arten von Informationen beschrÃ¤nkt, die üblicherweise auf einer Visitenkarte zu finden sind, einschlieÃŸlich, aber nicht beschrÃ¤nkt auf:",
    "privacyPage.firstLastName": "Ihr Vor- und Nachname;",
    "privacyPage.jobTitle": "Ihre Berufsbezeichnung/Position;",
