    "privacyPage.phoneNumber": "Ihre Telefonnummer.",
    "privacyPage.websiteBrowsing": "WÃ¤hrend des Website-Browsings gesammelte Informationen",
    "privacyPage.websiteBrowsingText": "ZusÃ¤tzlich zu den Informationen, die Sie uns freiwillig zur Verfügung stellen, sammeln wir auch die folgenden technischen Informationen, die unter bestimmten Bedingungen als personenbezogene Daten betrachtet werden kÃ¶nnen:",
    "privacyPage.ipAddresses": "IP-Adressen und/oder DomÃ¤nennamen der Computer, die für den Zugriff auf unsere Dienste verwendet werden;",
    "privacyPage.uriAddresses": "URI (Uniform Resource Identifier) Adressen der Ressourcen, die Ihr Browser anfordert;",
