    "privacyPage.responseStatus": "Numerischer Code, der den Antwortstatus des Servers angibt (Erfolg, Fehler, usw.);",
    "privacyPage.operatingSystem": "Parameter im Zusammenhang mit dem von Ihnen verwendeten Betriebssystem.",
    "privacyPage.useAndSharing": "Verwendung und Weitergabe Ihrer personenbezogenen Daten",
    "privacyPage.useAndSharingText1": "Alle personenbezogenen Daten, die Sie uns zur Verfügung stellen, werden verwendet, um die hÃ¶chste QualitÃ¤t unserer Dienstleistungen und Informationen zu liefern, wie in diesem Dokument beschrieben. Wir werden Ihre personenbezogenen Daten niemals an jemanden verkaufen, noch werden wir sie ohne Autorisierung weitergeben.",
    "privacyPage.useAndSharingText2": "Derzeit geben wir Ihre personenbezogenen Daten nicht an Dritte weiter. Wir kÃ¶nnen jedoch planen, in Zukunft Dienste von Drittanbietern zu nutzen, um Ihnen Informationen über unsere AktivitÃ¤ten, ArbeitsplÃ¤ne, Produktübersichten usw. zu senden, vorausgesetzt, Sie haben dem zugestimmt. Dies wird Teil einer aktualisierten Datenschutzrichtlinie sein, und Sie werden über eine Ankündigung auf unserer Website informiert.",
    "privacyPage.useAndSharingText3": "Personenbezogene Daten, die wÃ¤hrend der Nutzung unserer Dienste erhalten werden, werden ausschlieÃŸlich verwendet, um anonyme statistische Informationen über unsere Website zu sammeln und ihre ordnungsgemÃ¤ÃŸe Funktionsweise zu überprüfen und die QualitÃ¤t unserer Dienste zu verbessern. Diese Daten werden sofort nach der Verarbeitung gelÃ¶scht.",
    "privacyPage.yourRights": "Ihre Rechte bezüglich des Schutzes personenbezogener Daten",
    "privacyPage.rightsText": "GemÃ¤ÃŸ dem Gesetz zum Schutz personenbezogener Daten haben Sie je nach Zweck und Grund der Verarbeitung Ihrer Daten bestimmte Rechte. Nachfolgend sind die wichtigsten Rechte aufgeführt, auf die Sie Anspruch haben:",
    "privacyPage.right1Title": "1. Recht auf Zugang",
    "privacyPage.right1Text": "Sie kÃ¶nnen jederzeit Kopien Ihrer personenbezogenen Daten anfordern, vorbehaltlich gesetzlicher Ausnahmen.",
    "privacyPage.right2Title": "2. Recht auf Berichtigung",
    "privacyPage.right2Text": "Sie kÃ¶nnen Berichtigungen ungenauer oder unvollstÃ¤ndiger Daten anfordern.",
    "privacyPage.right3Title": "3. Recht auf LÃ¶schung",
    "privacyPage.right3Text": "Unter bestimmten Bedingungen kÃ¶nnen Sie die LÃ¶schung Ihrer personenbezogenen Daten beantragen.",
    "privacyPage.right4Title": "4. Recht auf EinschrÃ¤nkung der Verarbeitung",
    "privacyPage.right4Text": "Sie kÃ¶nnen eine eingeschrÃ¤nkte Verarbeitung Ihrer Daten unter bestimmten Bedingungen beantragen.",
    "privacyPage.right5Title": "5. Recht auf Widerspruch",
    "privacyPage.right5Text": "Sie kÃ¶nnen der Verarbeitung von Daten widersprechen, wenn sie nicht in unsere gesetzlichen Verpflichtungen oder berechtigten Interessen fÃ¤llt.",
    "privacyPage.right6Title": "6. Recht auf Datenübertragbarkeit",
    "privacyPage.right6Text": "Sie kÃ¶nnen beantragen, dass Ihre Daten an eine andere Organisation übertragen oder Ihnen direkt zur Verfügung gestellt werden.",
    "privacyPage.right7Title": "7. Recht auf Beschwerde",
    "privacyPage.right7Text": "Wenn Sie unzufrieden sind, kÃ¶nnen Sie eine Beschwerde bei der Agentur für den Schutz personenbezogener Daten unter",
    "privacyPage.contactUs": "Kontaktieren Sie uns",
    "privacyPage.contactText": "Wenn Sie Fragen zu dieser Datenschutzrichtlinie oder unseren Datenpraktiken haben, kontaktieren Sie uns bitte:",
