    // About Us Page
    "aboutUs.title": "Urban Rohr GmbH - Ãœber uns",
    "aboutUs.heroTitle": "Ihr erfahrener Partner seit über 20 Jahren",
    "aboutUs.heroSubtitle":
      "Ihr erfahrener Partner seit über 20 Jahren",
    "aboutUs.companyOverview": "Unternehmensübersicht",
    "aboutUs.missionTitle": "Mission",
    "aboutUs.missionText":
      "Die Urban Rohr GmbH fÃ¶rdert den Einsatz modernster Technologien unter strenger Einhaltung europÃ¤ischer Standards. Mit zertifizierter QualitÃ¤t, wettbewerbsfÃ¤higen Preisen und einem klaren Bekenntnis zu Ã¶kologischer Verantwortung stellen wir sicher, dass unsere Rohrsysteme hÃ¶chsten Anforderungen gerecht werden.",
    "aboutUs.visionTitle": "Vision",
    "aboutUs.visionText":
      "Unsere Vision ist es, als führendes Unternehmen in der Region für Entwicklung und Produktion hochwertiger Rohrsysteme für Infrastruktur- und Industriebauten anerkannt zu werden. Mit einer modernen Fertigung und einem umweltfreundlichen Ansatz schaffen wir sichere und nachhaltige LÃ¶sungen für unsere Partner und Kunden weltweit.",
    "aboutUs.valuesTitle": "Werte",
    "aboutUs.valuesText":
      "Bei der Urban Rohr GmbH stehen QualitÃ¤t, Nachhaltigkeit und Sicherheit im Mittelpunkt. Wir setzen auf umweltfreundliche Materialien, verantwortungsbewusste Prozesse und den Schutz unserer Mitarbeiter. Unser Ziel ist es, die Branche durch Innovation, VerlÃ¤sslichkeit und nachhaltige Produkte aktiv mitzugestalten.",
    "aboutUs.timelineTitle": "Unsere Reise",
    "aboutUs.projectsTitle": "Projekte",
