    "aboutUs.isoCertified": "ISO-zertifiziert",
    "aboutUs.corporate2024": "Corporate 2024",
    "aboutUs.companyStoryText1":
      "Urban Rohr GmbH â€“ Ihr Partner für Rohrsysteme",
    "aboutUs.companyStoryText2":
      "Die Urban Rohr GmbH ist ein international ausgerichtetes Unternehmen, das seit über 20 Jahren erfolgreich im Bereich moderner Rohrsysteme tÃ¤tig ist. Mit einer breiten Produktpalette von über 9.000 Artikeln â€“ darunter Rohre und LÃ¶sungen aus PE (Polyethylen), PP (Polypropylen), Guss und PVC â€“ beliefern wir Bau-, Infrastruktur- und Industrieprojekte in 16 LÃ¤ndern.",
    "aboutUs.companyStoryText3":
      "Unsere Rohrsysteme decken alle relevanten Anwendungsbereiche ab: Wasserversorgung, Abwasserentsorgung, Gas- und Ã–lleitungen, Telekommunikationsschutz, EntwÃ¤sserung sowie SchÃ¤chte und Fittings in allen Dimensionen von 12 mm bis 2000 mm.",
    "aboutUs.companyStoryText4":
      "Bekannt sind wir für hÃ¶chste QualitÃ¤t, FlexibilitÃ¤t und VerlÃ¤sslichkeit â€“ Faktoren, die uns in einem komplexen Marktumfeld auszeichnen. Durch kontinuierliche Investitionen in innovative Technologien, nachhaltige Prozesse und modernste Standards sichern wir uns langfristig eine starke Position im internationalen Wettbewerb. Die Kombination aus Erfahrung, Produktvielfalt und Innovationskraft macht die Urban Rohr GmbH zu einem verlÃ¤sslichen Partner für groÃŸe wie kleine Infrastrukturprojekte â€“ im In- und Ausland.",
    "aboutUs.since1975": "Seit 1975",
    "aboutUs.leadershipMessage": "Botschaft der GeschÃ¤ftsführung",
    "aboutUs.leadershipTitle": "Die Zukunft der Infrastruktur gemeinsam gestalten",
    "aboutUs.leadershipDescription1": "Bei der Urban Rohr GmbH ist unsere Mission klar: Wir wollen mit Innovationen vorangehen, Rohrsysteme nach hÃ¶chsten europÃ¤ischen Standards liefern und unseren Kunden stets einen Schritt voraus sein. Unsere StÃ¤rke liegt in nachhaltigen LÃ¶sungen, kontinuierlicher Expansion in internationale MÃ¤rkte und dem Anspruch, Wissen und Erfahrung mit Partnern zu teilen, die mit uns wachsen wollen.",
    "aboutUs.leadershipDescription2": "Gemeinsam bauen wir nicht nur für die Anforderungen von heute, sondern für eine Zukunft, die kommende Generationen stolz macht. Vertrauen, QualitÃ¤t und Innovation sind dabei die Eckpfeiler unseres Handelns.",
    "aboutUs.leaderName": "â€” Xhevxhet Ajeti, Louis de Paris, Xhemail Jashari & Zekirja Bajrami",
