    "ctpFittings.heroBadge": "GFK FORMSTÃœCKE",
    "ctpFittings.heroTitle": "Formstücke",
    "ctpFittings.heroDescription": "Die GFK-Formstücke bieten hochwertige LÃ¶sungen für zuverlÃ¤ssige und leistungsfÃ¤hige Rohrleitungssysteme. Gefertigt aus glasfaserverstÃ¤rktem Polyesterharz (GFK) zeichnen sie sich durch hohe mechanische Festigkeit, ausgezeichnete KorrosionsbestÃ¤ndigkeit und eine lange Nutzungsdauer aus. Die gemÃ¤ÃŸ internationalen Normen entwickelten und produzierten GFK-Formstücke sind vielseitig einsetzbar, unter anderem in Trinkwasserleitungen, Abwasser- und EntwÃ¤sserungssysteme, Industrieanlagen und Kraftwerksanwendungen. Dank flexibler EinbaumÃ¶glichkeiten und hoher Dichtheit gewÃ¤hrleisten sie maximale Betriebssicherheit, Effizienz und Langlebigkeit in anspruchsvollen Infrastrukturprojekten.",
