    // CTP Mansons Page
    "ctpMansons.pageTitle": "GFK Muffe/Kupplung",
    "ctpMansons.metaDescription": "SUPERLIT CTP Full-FaceÂ® Kupplungen bieten überlegene Sicherheit und Haltbarkeit bei Rohrverbindungen.",
    "ctpMansons.heroBadge": "Muffe/Kupplung",
    "ctpMansons.heroTitle": "GFK Full-Face Muffe / Kupplung",
    "ctpMansons.heroDescription": "Die GFK Full-Face Muffen/Kupplungen bieten hÃ¶chste Sicherheit und Langlebigkeit bei Rohrverbindungen. Durch die vollstÃ¤ndig mit einer EPDM-Dichtung ausgekleidete InnenflÃ¤che gewÃ¤hrleisten sie selbst bei hohen Betriebsdrücken eine zuverlÃ¤ssige und dauerhafte Dichtheit und bieten eine hÃ¶here Verbindungssicherheit im Vergleich zu herkÃ¶mmlichen Kupplungssystemen.\n\nDas integrierte Dichtungssystem verhindert ein Verrutschen oder HerauslÃ¶sen der Dichtung und macht eine separate Montage der Dichtung auf der Baustelle überflüssig. Dadurch wird eine schnelle, sichere und fehlerfreie Installation ermÃ¶glicht.",
    "ctpMansons.heroFeature1": "EPDM-Dichtung",
    "ctpMansons.heroFeature2": "Hohe DruckbestÃ¤ndigkeit",
    "ctpMansons.heroFeature3": "Einfache Montage",
    "ctpMansons.tab1Label": "PRODUKTBESCHREIBUNG",
    "ctpMansons.tab2Label": "KUPPLUNGSDURCHMESSER",
    "ctpMansons.tab3Label": "WINKELABWEICHUNG",
    "ctpMansons.tab1Title1": "CTP Full-FaceÂ®",
    "ctpMansons.tab1Title2": "GFK Full-Face Muffe/Kupplung",
    "ctpMansons.tab1ShortDesc": "Die GFK Full-Face Muffen/Kupplungen bieten hÃ¶chste Sicherheit und Langlebigkeit bei Rohrverbindungen. Die vollstÃ¤ndig mit einer EPDM-Dichtung ausgekleidete InnenflÃ¤che gewÃ¤hrleistet eine zuverlÃ¤ssige Wasserdichtheit selbst bei hohen Betriebsdrücken.\n\nDas integrierte Dichtungssystem verhindert ein Verrutschen oder HerauslÃ¶sen der Dichtung und macht eine separate Montage der Dichtung auf der Baustelle überflüssig. Dadurch wird eine schnelle, sichere und fehlerfreie Installation ermÃ¶glicht.",
    "ctpMansons.tab1LongDesc": "SUPERLIT GFK-Rohre, die sowohl im Schleudergussverfahren als auch im kontinuierlichen Filamentwickelverfahren hergestellt werden, besitzen bei gleicher Nennweite (DN) den gleichen AuÃŸendurchmesser. Dadurch kÃ¶nnen â€“ unabhÃ¤ngig vom Herstellungsverfahren â€“ dieselben SUPERLIT Full-FaceÂ® Kupplungen für Rohre mit identischer Nennweite verwendet werden.\n\nDank ihres geringen Eigengewichts und der einfachen Montage reduzieren sie Installationszeit und Kosten bei Infrastruktur-, Bau- und Industrieprojekten. Ihre hohe Korrosions- und ChemikalienbestÃ¤ndigkeit sorgt für eine lange Lebensdauer. Zudem werden sie aus umweltfreundlichen Materialien hergestellt und eignen sich daher besonders für nachhaltige Infrastrukturprojekte.\n\nMit diesen fortschrittlichen Kupplungssystemen verfolgt SUPERLIT das Ziel, maximale Betriebssicherheit, Effizienz und ZuverlÃ¤ssigkeit in modernen Rohrleitungssystemen zu gewÃ¤hrleisten.",
    "ctpMansons.tab2Title": "Durchmesserbereich der GFK Full-Face Muffen/Kupplungen",
    "ctpMansons.tab2Desc": "Die GFK Full-Face Kupplungen sind für einen breiten Nennweitenbereich ausgelegt und eignen sich daher für unterschiedlichste Infrastruktur- und Industrieprojekte.\n\nSie werden in Nennweiten von DN 300 bis DN 4000 gefertigt und bieten eine zuverlÃ¤ssige LÃ¶sung für Rohrverbindungen mit hoher DruckbestÃ¤ndigkeit und ausgezeichneter Dichtleistung.\n\nDank flexibler FertigungsmÃ¶glichkeiten stellen GFK Full-Face Kupplungen eine optimale Wahl für den Einsatz in verschiedensten Infrastruktur-, Wasser- und Industrieanwendungen dar.",
    "ctpMansons.tab2TableTitle": "GFK-Kupplungen â€“ Durchmesser- und Drucktabelle (Full-Face)",
    "ctpMansons.tab2Header1": "Nennweite DN",
    "ctpMansons.tab2Header2": "Muffenbreite",
    "ctpMansons.tab2Header3": "Muffen-AuÃŸendurchmesser (mm)",
    "ctpMansons.tab2ColDN": "DN (mm)",
    "ctpMansons.tab2ColW": "W (mm)",
    "ctpMansons.tab3Title": "Winkelabweichung bei GFK-Kupplungen/Muffen",
    "ctpMansons.tab3Desc": "Die GFK-Kupplungen vereinen FlexibilitÃ¤t und Sicherheit in modernen Rohrleitungssystemen. Sie werden gemÃ¤ÃŸ den Leistungsanforderungen der Normen EN 1119, ISO 8639 und ASTM 4161 entwickelt und geprüft. Diese Normen berücksichtigen unter anderem Kriterien wie Winkelabweichung (angular deflection), Druckbelastung, Ã¤uÃŸere Lasten sowie VakuumbestÃ¤ndigkeit.\n\nEin wesentliches Merkmal dieser Kupplungen ist ihre FÃ¤higkeit, Winkelabweichungen wÃ¤hrend der Rohrverlegung aufzunehmen. Die in den genannten Normen zulÃ¤ssigen Winkelabweichungen ermÃ¶glichen die Installation von Rohrleitungen auch in anspruchsvollem GelÃ¤nde oder bei komplexen Trassenführungen, ohne dass zusÃ¤tzliche Formstücke oder Verbindungselemente erforderlich sind.\n\nDurch diese FlexibilitÃ¤t erleichtern GFK-Kupplungen die Rohrverlegung erheblich, beschleunigen den Installationsprozess und gewÃ¤hrleisten gleichzeitig eine dauerhafte und leckagefreie Verbindung.",
    "ctpMansons.tab3ColPipe": "Rohrdurchmesser",
    "ctpMansons.tab3ColDeflection": "Maximal anwendbare Winkelabweichung an der Kupplung (Grad)",

