    "ctpKayarManson.pageTitle": "CTP Full-FaceÂ® Kayar ManÅŸon",
    "ctpKayarManson.heroTitle": "CTP Full-FaceÂ® Kayar ManÅŸon",
    "ctpKayarManson.heroDesc": "Developed as a result of SUPERLIT's R&D studies, the CTP Sliding Sleeve offers an excellent solution for pipeline repair and closing of assembly gaps. Thanks to its profile structure that can move in both directions, it is effective in the repair of damaged pipeline lines and in solving technical problems such as intermediate closure. It provides long-lasting and reliable performance with corrosion-resistant CTP composite material.",
