    "ctpKayarManson.tab1Title2": "KAYAR MANÅžON",
    "ctpKayarManson.tab1ShortDesc": "The CTP Sliding Sleeve, developed through SUPERLIT's R&D efforts, provides an excellent solution for pipeline repair and closing assembly gaps. Its bidirectional profile structure makes it effective for repairing damaged pipelines.",
    "ctpKayarManson.tab1LongDesc": "Developed as a result of SUPERLIT's R&D studies, the CTP Kayar ManÅŸon (Sliding Sleeve) offers an excellent solution for pipeline repair and closing of assembly gaps. Thanks to its profile structure that can move in both directions, it is effective in the repair of damaged pipeline lines. SUPERLIT is the only pipe manufacturer in Turkey that can produce glass fiber reinforced polyester (CTP) pipes with 3 different technologies.",
