    "ctpJackingManson.heroDesc": "SUPERLITs neu entwickelte CTP Jacking Manschetten sind als korrosionsbestÃ¤ndige Alternative zu Stahlmanschetten für grabenlose Anwendungen konzipiert. In aggressiven Bodenumgebungen, in denen Metallmanschetten aufgrund von Korrosion eine begrenzte Lebensdauer haben, bietet die CTP-Verbundstruktur eine langlebige und robuste LÃ¶sung.",
