    // Marine Lug Page
    "marineLug.pageTitle": "Aqua-Montagesystem",
    "marineLug.heroTitle": "Aqua-Montagesystem / Unterwasser-Rohrinstallationssystem",
    "marineLug.heroDesc": "Das speziell entwickelte Aqua-Montagesystem, das patentiert wurde, stellt eine innovative LÃ¶sung für die Unterwasserverlegung von groÃŸdimensionierten Rohrleitungen dar.\n\nDieses System wurde speziell für die Installation von Rohrleitungen mit groÃŸen Durchmessern unter Wasser konzipiert und vereinfacht den gesamten Verlegeprozess erheblich.\n\nDie Aqua-Montagesystem ermÃ¶glichen eine einfache, sichere und effiziente Montage von Rohrleitungen unter Wasser und tragen damit zu einer schnelleren und zuverlÃ¤ssigeren Installation bei maritimen Infrastrukturprojekten bei.",
    "marineLug.badge1": "Patentiertes Design",
    "marineLug.badge2": "Einfache Montage",
    "marineLug.badge3": "Hohe Haltbarkeit",
    "marineLug.tab1Label": "PRODUKTBESCHREIBUNG",
    "marineLug.tab2Label": "BILDGALERIE",
    "marineLug.tab3Label": "VIDEOGALERIE",
    "marineLug.tab1SystemsTitle": "Aqua-Montagesystem",
    "marineLug.tab1ShortDesc": "Zu den innovativen Ingenieurlösungen gehört das Aqua-Montagesystem – ein patentiertes System zur Unterwasserverlegung von Rohrleitungen, das speziell für die Installation von Rohrleitungen mit großen Durchmessern entwickelt wurde.",
    "marineLug.details": "DETAILS",
    "marineLug.tab1WhatTitle": "Was ist ein Unterwasser-Rohrinstallationssystem?",
    "marineLug.tab1WhatDesc": "Unterwasser-Rohrinstallationssystem ist ein System, das die Montage von Rohrleitungen unter Wasser erleichtert und gleichzeitig sicherstellt, dass die Rohre während der Installation stabil in ihrer Position bleiben, bis der Verfüllvorgang abgeschlossen ist.\n\nDank der Stahl-Lug-Ringe und der benutzerfreundlichen Konstruktion ermöglichen Unterwasser-Rohrinstallationssysteme eine sichere, effiziente und wirtschaftliche Verlegung von Rohrleitungen unter Wasser. Gleichzeitig wird die Sicherheit von Tauchern erhöht, während Unternehmen von reduzierten Installationskosten und kürzeren Bauzeiten profitieren.",
    "marineLug.tab1AdvTitle": "Vorteile der Aqua-Montagesysteme:",
    "marineLug.tab1Adv1": "Stahl-Lug-Ringe: Die aus hochfestem Stahl gefertigten Lug-Ringe sorgen dafür, dass die Rohre während der Unterwasserinstallation sicher in ihrer Position bleiben.",
    "marineLug.tab1Adv2": "Drehmechanismus: Durch die Drehfunktion lassen sich die Lug-Elemente leicht in ihre vorgesehenen Aufnahmen einsetzen, was die Montage deutlich erleichtert.",
    "marineLug.tab1Adv3": "Einfache Demontage: Nach Abschluss der Rohrverlegung können die Lug-Ringe problemlos entfernt werden, wodurch das System flexibel und wiederverwendbar bleibt.",
    "marineLug.tab1Adv4": "Schnelle und einfache Installation: Die neu entwickelten Aqua-Montagesysteme ermöglichen eine besonders schnelle und unkomplizierte Montage und sparen dadurch Zeit und Arbeitsaufwand.",
    "marineLug.tab1UsageTitle": "Anwendungen und Eigenschaften",
    "marineLug.tab1UsageDesc": "Aqua-Montagesysteme sind besonders wichtig für Unterwasserarbeiten durch Taucher, deren Arbeitszeit unter Wasser begrenzt ist. Das System ermöglicht eine schnelle, sichere und präzise Verlegung von Rohrleitungen, wodurch Risiken für Taucher reduziert und Projektzeiten verkürzt werden.\n\nUnternehmen profitieren gleichzeitig von höherer Effizienz, geringeren Kosten und einem optimierten Installationsprozess.",
    "marineLug.tab1FeatTitle": "Produkteigenschaften:",
    "marineLug.tab1Feat1": "Stahl-Lug-Ringe – hohe Stabilität und lange Lebensdauer",
    "marineLug.tab1Feat2": "Drehmechanismus – erleichtert die Installation",
    "marineLug.tab1Feat3": "Einfache Demontage – hohe Flexibilität und Wiederverwendbarkeit",
    "marineLug.tab1Feat4": "Schnelle Produktion und Installation – Zeit- und Kosteneinsparungen",
    "marineLug.tab1WhyTitle": "Warum Aqua-Montagesysteme?",
    "marineLug.tab1WhyDesc": "Die Aqua-Montagesysteme bieten eine zuverlässige, wirtschaftliche und sichere Lösung für die Unterwasserverlegung von Rohrleitungen. Ihr innovatives Design verbessert die Arbeitssicherheit für Taucher, beschleunigt Installationsprozesse und erhöht die Effizienz bei maritimen Infrastrukturprojekten.",
    "marineLug.video1Title": "Wie werden CTP-Rohre unter Wasser verlegt? Lernen Sie das patentierte Marine Lug Produkt von Superlit kennen.",
    "marineLug.video2Title": "Superlit CTP Rohr â€“ Ä°skenderun â€“ Hatay 2 x 600 MW WÃ¤rmekraftwerk Projekt â€“ ATLAS â€“ Projektvorstellung",
    "marineLug.video3Title": "Superlit CTP Rohr â€“ Karabiga â€“ Ã‡anakkale 1320 MW WÃ¤rmekraftwerk Projekt â€“ CENAL â€“ Projektvorstellung",
    "marineLug.video4Title": "DN4000 und DN3800 Seeleitungsrohr-Montage beim CENAL WÃ¤rmekraftwerk Projekt",

    // Dark Liner Page
    "darkLiner.pageTitle": "PowerLiner GFK-Rohr",
    "darkLiner.heroTitle": "PowerLiner GFK-Rohr",
    "darkLiner.heroDesc": "Das Superlit Dark Liner GFK-Rohr, eines der neuesten von Superlit Pipe entwickelten Produkte, bietet dank seines weiterentwickelten Designs, optimierter Herstellungsverfahren und hochwertiger Materialien hervorragende technische Eigenschaften und Leistungsmerkmale.",
