    "darkLiner.tab1Label": "PRODUKTBESCHREIBUNG",
    "darkLiner.tab1SectionTitle": "PowerLiner GFK-Rohr",
    "darkLiner.tab1ShortDesc": "Das PowerLiner GFK-Rohr, eine der neuesten Innovationen PowerLiner GFK-Rohr, stellt einen bedeutenden Fortschritt in der Rohrtechnologie dar. Durch sein innovatives Design, fortschrittliche Herstellungsverfahren und hochwertige Materialien bietet dieses Rohrsystem verbesserte technische Eigenschaften und eine besonders hohe Leistungsfähigkeit.",
    "darkLiner.details": "DETAILS",
    "darkLiner.tab1ProductDescTitle": "Produktbeschreibung",
    "darkLiner.tab1DescIntro": "Dieses neu entwickelte Rohrsystem bietet deutliche Vorteile in Bezug auf:",
    "darkLiner.tab1DescBullet1": "Schlagfestigkeit",
    "darkLiner.tab1DescBullet2": "Abriebfestigkeit",
    "darkLiner.tab1DescBullet3": "Beständigkeit gegenüber Hochdruck-Wasserstrahlen",
    "darkLiner.tab1DescBullet4": "Chemische Beständigkeit",
    "darkLiner.tab1Desc": "Dank einer speziell entwickelten Innenliner-Schicht, die auf der über 60-jährigen Erfahrung basiert, bietet dieses verbesserte Rohrsystem eine zusätzliche Widerstandsfähigkeit gegenüber abrasiven Medien und Feststoffanteilen in Flüssigkeiten. Dadurch erhalten Planer und Betreiber eine besonders langlebige und zuverlässige Rohrlösung für anspruchsvolle Anwendungen:",
    "darkLiner.tab1AdvTitle": "Produktvorteile",
