    "darkLiner.tab1Adv4": "Erhöhte chemische Beständigkeit",

    // Trenchless Systems Page
    "trenchless.pageTitle": "Grabenlose Systeme (Jacking & Re-Lining)",
    "trenchless.heroTitle": "Grabenlose Systeme (Rohrvortrieb & Relining)",
    "trenchless.heroDesc": "Die grabenlosen Bauverfahren Rohrvortrieb (Jacking) und Relining ermöglichen die Modernisierung und den Ausbau bestehender Infrastrukturen in urbanen Gebieten, ohne das Stadtleben oder den Verkehrsfluss wesentlich zu beeinträchtigen.",
    "trenchless.badge1": "Keine Grabung erforderlich",
    "trenchless.badge2": "Kosteneffizient",
    "trenchless.badge3": "Minimale Störung",
    "trenchless.tab1Label": "PRODUKTBESCHREIBUNG",
    "trenchless.tab2Label": "BILDGALERIE",
    "trenchless.tab1Title1": "Grabenlose Systeme",
    "trenchless.tab1Title2": "Rohrvortrieb (Jacking) & Relining:",
    "trenchless.tab1ShortDesc": "Rohre, die zur Sanierung oder zum Ersatz bestehender Rohrleitungen eingesetzt werden, bieten hervorragende Lösungen im Bereich der grabenlosen Bauverfahren. Diese Technologien ermöglichen die Erneuerung von Rohrleitungen, die das Ende ihrer Nutzungsdauer erreicht haben oder ersetzt werden müssen.",
    "trenchless.details": "DETAILS",
    "trenchless.tab1MethodsIntro": "Dabei kommen verschiedene Methoden zum Einsatz, darunter:",
    "trenchless.tab1Method1": "Relining-Verfahren, bei denen neue Rohre in bereits vorhandene Rohrleitungen eingezogen werden.",
    "trenchless.tab1Method2": "Rohrvortrieb (Jacking), bei dem Rohrleitungen mit speziellen Vortriebsmaschinen durch unterirdisch hergestellte Tunnel verlegt werden.",
    "trenchless.tab1DescAfterMethods": "Diese Verfahren ermöglichen eine effiziente und wirtschaftliche Rohrverlegung, ohne umfangreiche Erdarbeiten durchführen zu müssen.",
    "trenchless.tab1AdvTitle": "Vorteile der Jacking- und Relining-Verfahren:",
    "trenchless.tab1Adv1": "Geringere Vortriebskräfte, wodurch Energie- und Betriebskosten reduziert werden",
    "trenchless.tab1Adv2": "Einfache und schnelle Installation",
    "trenchless.tab1Adv3": "Reduzierte Projektkosten durch weniger Aushubarbeiten und geringeren Maschineneinsatz",
    "trenchless.tab1Adv4": "Aufnahme von Winkelabweichungen, wodurch eine flexible Trassenführung möglich ist",
    "trenchless.tab1Adv5": "Keine offenen Gräben erforderlich, wodurch Umweltbelastungen minimiert werden",
    "trenchless.tab1Adv6": "Anwendbar auch bei ungünstigen Wetterbedingungen",
    "trenchless.tab1Adv7": "Keine Eingriffe in den Wasserstand erforderlich",
    "trenchless.tab1Adv8": "Kein großer Lagerplatz für Materialien notwendig",
    "trenchless.tab1Adv9": "Minimale Lärm- und Umweltbelastung",
    "trenchless.tab1ClosingNote": "Die grabenlosen Technologien machen Infrastrukturprojekte schneller, wirtschaftlicher und umweltfreundlicher und eignen sich sowohl für Neubauprojekte als auch für die Sanierung bestehender Leitungsnetze.",
    "trenchless.tab1TablesTitle": "Bemessungstabellen für Jacking-Rohre",
    "trenchless.tab1TablesDesc": "Laden Sie die Datendatei der gewünschten Bemessungstabelle auf Ihren Computer herunter.",

